function formatOptionTerm(opt: Option): string {
	const parts: string[] = [];
	if (opt.short) parts.push(opt.short);
	if (opt.long) parts.push(opt.long);
	let term = parts.join(", ");

	// Append value placeholder for non-boolean options
	if (opt.flags) {
		const match = opt.flags.match(/<[^>]+>|\[[^\]]+\]/);
		if (match) {
			term += ` ${match[0]}`;
		}
	}
	return term;
}

