    rerank: bool = False,
    keyword: bool = False,
    filters: dict | None = None,
    fields: list[str] | None = None,
    show_expired: bool = False,
    reference_date: str | None = None,
    latest_only: bool = False,
) -> list[dict]:
    payload: dict[str, Any] = {"query": query, "top_k": top_k, "threshold": threshold}

    api_filters = self._build_filters(
        user_id=user_id,
        agent_id=agent_id,
        app_id=app_id,
        run_id=run_id,
        extra_filters=filters,
    )
    if api_filters:
        payload["filters"] = api_filters
    if rerank:
        payload["rerank"] = True
    if keyword:
        payload["keyword_search"] = True
    if fields:
        payload["fields"] = fields
    if show_expired:
        payload["show_expired"] = True
    if reference_date is not None:
        payload["reference_date"] = reference_date
    if latest_only:
        payload["latest_only"] = True
    payload["source"] = "CLI"

    result = self._request("POST", "/v3/memories/search/", json=payload)
    return (
        result
        if isinstance(result, list)
        else result.get("results", result.get("memories", []))
    )

