interface MemoryLike {
  id: string;
  memory?: string;
  categories?: string[];
  createdAt?: Date | string;
}

function formatAge(date: Date | string): string {
  const minutes = Math.floor((Date.now() - new Date(date).getTime()) / 60_000);
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  return hours < 24 ? `${hours}h ago` : `${Math.floor(hours / 24)}d ago`;
}

function formatMemoryCompact(memory: MemoryLike): string {
  const category = memory.categories?.[0] ?? "uncategorized";
  const age = memory.createdAt ? ` (${formatAge(memory.createdAt)})` : "";
  return `[${category}] ${memory.memory ?? "(empty)"}${age} [mem0:${memory.id}]`;
}

function formatMemoryList(memories: MemoryLike[]): string {
  return memories.length
    ? memories.map((memory, index) => `${index + 1}. ${formatMemoryCompact(memory)}`).join("\n")
    : "No memories found.";
}

function formatAddResult(result: unknown): string {
  const items: MemoryLike[] = Array.isArray(result)
    ? result
    : ((result as { results?: MemoryLike[] } | null)?.results ?? (result ? [result as MemoryLike] : []));
  const pending = items.find((item) => (item as { status?: string }).status === "PENDING") as
    | { eventId?: string; event_id?: string }
    | undefined;
  if (pending) {
    const id = pending.eventId ?? pending.event_id;
    return `Memory queued for background extraction${id ? ` (event ${id})` : ""}; it will be searchable shortly.`;
  }
  if (!items.length) return "Memory stored.";
  return `Stored ${items.length} ${items.length === 1 ? "memory" : "memories"}:\n${formatMemoryList(items)}`;
}

function groupByCategory(memories: MemoryLike[]): Map<string, MemoryLike[]> {
  const groups = new Map<string, MemoryLike[]>();
  for (const memory of memories) {
    const category = memory.categories?.[0] ?? "uncategorized";
    groups.set(category, [...(groups.get(category) ?? []), memory]);
  }
  return groups;
}

function truncateOutput(
  text: string,
  maxChars = MAX_OUTPUT_CHARS,
  maxLines = MAX_OUTPUT_LINES,
): string {
  const lines = text.split("\n");
  if (lines.length <= maxLines && text.length <= maxChars) return text;
  const kept = lines.slice(0, maxLines);
  let result = kept.join("\n");
  const charCapped = result.length > maxChars;
  if (charCapped) result = result.slice(0, maxChars);
  const reasons = [];
  if (kept.length < lines.length) reasons.push(`showing ${kept.length} of ${lines.length} lines`);
  if (charCapped) reasons.push(`cut at ${Math.floor(maxChars / 1000)}KB`);
  return `${result}\n\n[Output truncated: ${reasons.join(", ")}]`;
}

interface EntityParams {
  userId?: string;
  agentId?: string;
  runId?: string;
}

function entitySearchFilters(
  params: EntityParams,
  defaultUserId: string,
): Record<string, string> {
  const filters: Record<string, string> = { user_id: clean(params.userId) ?? defaultUserId };
  const agentId = clean(params.agentId);
  const runId = clean(params.runId);
  if (agentId) filters.agent_id = agentId;
  if (runId) filters.run_id = runId;
  return filters;
}

function entityAddParams(params: EntityParams, defaultUserId: string): Record<string, string> {
  const values: Record<string, string> = { userId: clean(params.userId) ?? defaultUserId };
  const agentId = clean(params.agentId);
  const runId = clean(params.runId);
  if (agentId) values.agentId = agentId;
  if (runId) values.runId = runId;
  return values;
}

function parseProjectFromRemote(remote: string): string | null {
  const match = remote.trim().match(/[:/]([^/:]+)\/([^/:]+?)(?:\.git)?\/?$/);
  return match ? `${match[1]}-${match[2]}` : null;
}

function redactSecrets(value: unknown): string {
  let text =
    typeof value === "string"
      ? value
      : (JSON.stringify(value, null, 0) ?? String(value));
  for (const [pattern, replacement] of SECRET_PATTERNS) text = text.replace(pattern, replacement);
  return text;
}

function boundedText(value: unknown, limit: number): string {
  const text = redactSecrets(value).trim();
  return text.length <= limit ? text : `${text.slice(0, limit)}\n...[truncated ${text.length - limit} chars]`;
}

interface MessageLike {
  role: string;
  content?: unknown;
}

function extractText(content: unknown): string | null {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return null;
  const text = content
    .filter(
      (block): block is { type: "text"; text: string } =>
        typeof block === "object" &&
        block !== null &&
        (block as { type?: unknown }).type === "text" &&
        typeof (block as { text?: unknown }).text === "string",
    )
    .map((block) => block.text)
    .join("\n");
  return text || null;
}

function extractConversation(
  messages: MessageLike[],
): Array<{ role: "user" | "assistant"; content: string }> {
  const conversation: Array<{ role: "user" | "assistant"; content: string }> = [];
  for (const message of messages) {
    if (message.role !== "user" && message.role !== "assistant") continue;
    const text = extractText(message.content);
    if (!text) continue;
    const content = redactSecrets(text).trim();
    if (content) conversation.push({ role: message.role, content });
  }
  return conversation;
}

interface RecallOptions {
  heading?: string;
  maxChars?: number;
  seenIds?: Set<string>;
  timeoutMs?: number;
}

interface MemoryLifecycleOptions {
  recallHeading?: string;
  maxContextChars?: number;
  recallTimeoutMs?: number;
}

class MemoryLifecycle {
  readonly #seenMemoryIds = new Set<string>();
  readonly #options: MemoryLifecycleOptions;

  constructor(options: MemoryLifecycleOptions = {}) {
    this.#options = options;
  }

  beginSession(): void {
    this.#seenMemoryIds.clear();
  }

  prepareConversation(
    messages: MessageLike[],
  ): Array<{ role: "user" | "assistant"; content: string }> {
    return extractConversation(messages);
  }

  prepareUserText(value: unknown): string {
    return redactSecrets(value).trim();
  }

  recall(
    prompt: string,
    enabled: boolean,
    search: (query: string) => Promise<{ results?: unknown[] }>,
  ): Promise<string> {
    return buildRecallContext(prompt, enabled, search, {
      heading: this.#options.recallHeading,
      maxChars: this.#options.maxContextChars,
      seenIds: this.#seenMemoryIds,
      timeoutMs: this.#options.recallTimeoutMs,
    });
  }
}

beginSession(): void {
    this.#seenMemoryIds.clear();
  }

prepareConversation(
    messages: MessageLike[],
  ): Array<{ role: "user" | "assistant"; content: string }> {
    return extractConversation(messages);
  }

prepareUserText(value: unknown): string {
    return redactSecrets(value).trim();
  }

recall(
    prompt: string,
    enabled: boolean,
    search: (query: string) => Promise<{ results?: unknown[] }>,
  ): Promise<string> {
    return buildRecallContext(prompt, enabled, search, {
      heading: this.#options.recallHeading,
      maxChars: this.#options.maxContextChars,
      seenIds: this.#seenMemoryIds,
      timeoutMs: this.#options.recallTimeoutMs,
    });
  }

function createMemoryLifecycle(
  options: MemoryLifecycleOptions = {},
): MemoryLifecycle {
  return new MemoryLifecycle(options);
}

async function buildRecallContext(
  prompt: string,
  enabled: boolean,
  search: (query: string) => Promise<{ results?: unknown[] }>,
  options: RecallOptions = {},
): Promise<string> {
  if (!enabled) return "";
  const query = boundedText(prompt, MAX_RECALL_QUERY_CHARS);
  if (!query) return "";

  try {
    let timer: ReturnType<typeof setTimeout> | undefined;
    let response: { results?: unknown[] } | null;
    try {
      const timeout = new Promise<null>((resolve) => {
        timer = setTimeout(() => resolve(null), options.timeoutMs ?? 2_000);
      });
      response = await Promise.race([search(query), timeout]);
    } finally {
      if (timer) clearTimeout(timer);
    }
    if (!response) return "";
    const memories = (response.results ?? []) as MemoryLike[];
    const unseen = memories.filter((memory) => !options.seenIds?.has(memory.id));
    if (!unseen.length) return "";

    const prefix = `<mem0-relevant-memories>\n${options.heading ?? RECALL_HEADING}\n`;
    const suffix = "\n</mem0-relevant-memories>";
    const maxChars = options.maxChars ?? DEFAULT_MAX_CONTEXT_CHARS;
    const lines: string[] = [];
    for (const memory of unseen) {
      const line = `${lines.length + 1}. ${redactSecrets(formatMemoryCompact(memory))
        .replace(/\s+/g, " ")
        .trim()}`;
      const candidate = prefix + [...lines, line].join("\n") + suffix;
      if (candidate.length > maxChars) {
        if (!lines.length) {
          const available = maxChars - prefix.length - suffix.length;
          if (available > 1) lines.push(`${line.slice(0, available - 1).trimEnd()}…`);
        }
        break;
      }
      lines.push(line);
      options.seenIds?.add(memory.id);
    }
    if (!lines.length) return "";
    if (unseen[0] && !options.seenIds?.has(unseen[0].id)) options.seenIds?.add(unseen[0].id);
    return prefix + lines.join("\n") + suffix;
  } catch {
    return "";
  }
}

interface ScopeContext {
  userId: string;
  appId: string;
  runId: string;
}

function normalizeScope(value: unknown): Scope {
  return value === "session" || value === "global" ? value : "project";
}

function resolveToolScope(requested: Scope | undefined, configured: Scope): Scope {
  const scope = requested ?? configured;
  if (scope === "global" && configured !== "global") {
    throw new Error("Select global scope in the plugin settings or /mem0-scope command first.");
  }
  return scope;
}

function validateContext(scope: Scope, context: ScopeContext): void {
  const keys: (keyof ScopeContext)[] = ["userId"];
  if (scope !== "global") keys.push("appId");
  if (scope === "session") keys.push("runId");
  for (const key of keys) {
    if (!context[key]?.trim() || /^\*+$/.test(context[key].trim())) {
      throw new Error(`Invalid memory scope ${key}`);
    }
  }
}

function scopeSearchFilters(scope: Scope, context: ScopeContext): Record<string, string> {
  validateContext(scope, context);
  if (scope === "session") {
    return { user_id: context.userId, app_id: context.appId, run_id: context.runId };
  }
  return scope === "global"
    ? { user_id: context.userId }
    : { user_id: context.userId, app_id: context.appId };
}

function scopeAddParams(scope: Scope, context: ScopeContext): Record<string, string> {
  validateContext(scope, context);
  if (scope === "session") {
    return { userId: context.userId, appId: context.appId, runId: context.runId };
  }
  return scope === "global"
    ? { userId: context.userId }
    : { userId: context.userId, appId: context.appId };
}

interface TelemetryConfig {
  host: string;
  source: string;
  version: string;
  distinctId: string | (() => string | undefined);
  delivery?: (batch: Record<string, unknown>[]) => void | Promise<void>;
  flushThreshold?: number;
  flushIntervalMs?: number;
  maxQueueSize?: number;
  commonProperties?: Record<string, unknown>;
  eventName?: (event: string) => string;
  enabled?: () => boolean;
}

function isTelemetryEnabled(): boolean {
  const value = process.env.MEM0_TELEMETRY;
  return value === undefined || !OFF_VALUES.has(value.toLowerCase());
}

function safeValue(value: unknown): unknown {
  if (typeof value === "string") return redactSecrets(value);
  if (Array.isArray(value)) return value.map(safeValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value)
        .filter(([key]) => !PRIVATE_KEYS.has(key.toLowerCase().replace(/[^a-z]/g, "")))
        .map(([key, nested]) => [key, safeValue(nested)]),
    );
  }
  return value;
}

function safeProperties(properties: Record<string, unknown>): Record<string, unknown> {
  return safeValue(properties) as Record<string, unknown>;
}

function errorKind(error: unknown): string {
  const text = (error instanceof Error ? error.message : String(error)).toLowerCase();
  if (text.includes("timeout") || text.includes("aborted")) return "timeout";
  if (text.includes("401") || text.includes("403") || text.includes("unauthor")) return "auth";
  if (text.includes("429") || text.includes("rate limit")) return "rate-limited";
  if (/50[0234]/.test(text)) return "server-error";
  if (text.includes("400") || text.includes("422")) return "bad-request";
  if (text.includes("fetch failed") || text.includes("enotfound")) return "network";
  return error instanceof Error ? error.constructor.name : "other";
}

function createTelemetry(config: TelemetryConfig) {
  let queue: Record<string, unknown>[] = [];
  let timer: ReturnType<typeof setInterval> | undefined;
  let consecutiveFailures = 0;
  let retryNotBefore = 0;
  let exitFlushAttempted = false;
  let flushing = false;
  const flushThreshold = config.flushThreshold ?? 10;
  const maxQueueSize = config.maxQueueSize ?? 100;

  const deliver = config.delivery ?? (async (batch: Record<string, unknown>[]) => {
    const response = await fetch(POSTHOG_BATCH_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ api_key: POSTHOG_API_KEY, batch }),
      signal: AbortSignal.timeout(3_000),
    });
    // fetch only rejects on a network-level failure. Without this check a 500,
    // a 503 or a 429 resolved normally and the batch was counted as delivered
    // and dropped, which is the likelier outage than a refused connection.
    // Any non-2xx is retried, matching the Python core: the backoff and the
    // queue bound contain a payload that will never be accepted, because the
    // re-queued batch sits at the front and is the first thing evicted.
    if (!response.ok) throw new Error(`posthog responded ${response.status}`);
  });

  async function flush(force = false): Promise<void> {
    // One at a time. Two overlapping flushes each detach the queue and each
    // prepend their own batch back on failure, so the later batch lands in front
    // of the earlier one and the truncation then drops the OLDER events first,
    // inverting the priority the failure path exists to establish. A second
    // caller returns immediately; the queue waits for the next flush.
    if (flushing) return;
    if (!queue.length) return;
    // `force` skips the cooldown. beforeExit is the last chance this process
    // gets, and gating it on the same backoff meant that after any failure the
    // exit flush did nothing and the queue died with the process, which is the
    // loss this whole mechanism exists to prevent.
    if (!force && Date.now() < retryNotBefore) return;
    const batch = queue;
    queue = [];
    flushing = true;
    try {
      await deliver(batch);
      consecutiveFailures = 0;
      retryNotBefore = 0;
    } catch {
      // Put it back. Detaching the batch and swallowing the error deleted the
      // events outright, so any blip silently dropped telemetry with nothing
      // recording that it had happened. Every event carries a uuid, so a retry
      // that duplicates one PostHog already accepted is collapsed there.
      //
      consecutiveFailures += 1;
      if (consecutiveFailures >= MAX_DELIVERY_ATTEMPTS) {
        // Give up on the queue so a failing outage cannot hold it for the
        // session. This drops whatever is queued now, which includes events
        // captured during the outage, not only the batch that kept failing.
        consecutiveFailures = 0;
        retryNotBefore = 0;
        return;
      }
      // Keep the FRONT on overflow, so the batch being retried survives and a
      // new event is what gets dropped. Matches the Python core, where record()
      // refuses new events once the spool is full rather than evicting the
      // backlog. Keeping the newest would throw away exactly the events this
      // retry exists to save.
      queue = [...batch, ...queue].slice(0, maxQueueSize);
      retryNotBefore = Date.now() + Math.min(2 ** consecutiveFailures * 1_000, RETRY_BACKOFF_CEILING_MS);
    } finally {
      flushing = false;
    }
  }

  function beforeExit(): void {
    // Once, and only once. Node re-emits beforeExit whenever the handler
    // schedules more async work, so an unconditional forced flush looped until
    // the attempt budget was spent: five attempts against a 3s delivery timeout
    // is fifteen seconds added to the shutdown of whatever editor or CLI is
    // hosting this. The backoff used to end that loop after one attempt, and
    // removing it for the forced path removed the only thing bounding it.
    if (exitFlushAttempted) return;
    exitFlushAttempted = true;
    void flush(true);
  }

  function build(event: string, properties: Record<string, unknown> = {}): Record<string, unknown> | null {
    if (!(config.enabled?.() ?? isTelemetryEnabled())) return null;
    try {
      const distinctId = typeof config.distinctId === "function" ? config.distinctId() : config.distinctId;
      if (!distinctId) return null;
      return {
        event: config.eventName?.(event) ?? event,
        distinct_id: distinctId,
        // Stamped once, at capture. This is what makes retrying safe: a batch
        // re-sent after a failure carries the same ids, so PostHog collapses
        // anything it already accepted instead of counting it twice.
        uuid: randomUUID(),
        // Capture time, not ingestion time. Events now sit through backoff and
        // across a whole outage, so without this PostHog records them whenever
        // delivery happened to succeed. It also matters for the uuid dedupe
        // above, whose key includes the event date.
        timestamp: new Date().toISOString(),
        properties: {
          ...safeProperties(properties),
          ...safeProperties(config.commonProperties ?? {}),
          host: config.host,
          source: config.source,
          language: "node",
          plugin_version: config.version,
          node_version: process.version,
          os: process.platform,
          $process_person_profile: false,
          $lib: "posthog-node",
        },
      };
    } catch {
      return null;
    }
  }

  function capture(event: string, properties: Record<string, unknown> = {}): void {
    try {
      const payload = build(event, properties);
      if (!payload) return;
      // Full means drop this event, not evict the backlog. Same rule as the
      // failure path above and as Python's record().
      if (queue.length >= maxQueueSize) return;
      queue.push(payload);
      if (!timer) {
        timer = setInterval(() => void flush(), config.flushIntervalMs ?? 5_000);
        timer.unref?.();
        process.on("beforeExit", beforeExit);
      }
      if (queue.length >= flushThreshold) void flush();
    } catch {
      // Telemetry must never affect plugin behavior.
    }
  }

  function resetForTesting(): void {
    queue = [];
    consecutiveFailures = 0;
    retryNotBefore = 0;
    if (timer) clearInterval(timer);
    timer = undefined;
    process.off("beforeExit", beforeExit);
  }

  return { build, capture, flush, resetForTesting, queueForTesting: () => queue };
}

