def is_enabled() -> bool:
    """Whether telemetry is switched on for this process."""
    return os.environ.get("MEM0_TELEMETRY", "true").strip().lower() not in {
        "false",
        "0",
        "no",
        "off",
    }

def _digest(value: str, length: int = 16) -> str:
    """Unsalted digest. Only for values that are already secrets (API keys)."""
    return hashlib.sha256(value.encode("utf-8")).hexdigest()[:length]

def _safe_value(value: Any) -> Any:
    if isinstance(value, str):
        return memory_core.redact(value)
    if isinstance(value, dict):
        return {
            key: _safe_value(item)
            for key, item in value.items()
            if "".join(character for character in str(key).lower() if character.isalnum())
            not in _PRIVATE_KEYS
        }
    if isinstance(value, (list, tuple)):
        return [_safe_value(item) for item in value]
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return memory_core.redact(value)

def _read_identity() -> dict[str, str]:
    try:
        value = json.loads(_identity_path().read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return value if isinstance(value, dict) else {}

def _write_identity(identity: dict[str, str]) -> None:
    path = _identity_path()
    temporary = path.with_suffix(f".{os.getpid()}.tmp")
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary.write_text(json.dumps(identity), encoding="utf-8")
        temporary.replace(path)
    except OSError:
        try:
            temporary.unlink()
        except OSError:
            pass

def _data_dir_has_content() -> bool:
    """Whether anything predates this session in the plugin data directory."""
    try:
        for entry in memory_core.data_dir().iterdir():
            if entry.name != "install-state.json":
                return True
    except OSError:
        pass
    return False

def _repair_install_state(path: Path) -> None:
    """Rewrite an unparseable marker so version tracking can resume."""
    try:
        temporary = path.with_suffix(f".{os.getpid()}.tmp")
        temporary.write_text(
            json.dumps({"plugin_version": memory_core.PLUGIN_VERSION, "repaired_at": memory_core.utc_now()}),
            encoding="utf-8",
        )
        temporary.replace(path)
    except OSError:
        pass

def record(
    event: str,
    *,
    repo: Any = None,
    session_id: str | None = None,
    **properties: Any,
) -> None:
    """Append one event to the local spool. Never blocks and never raises."""
    if not is_enabled():
        return
    try:
        spool = _spool_path()
        try:
            if spool.stat().st_size > SPOOL_LIMIT_BYTES:
                return
        except OSError:
            pass
        properties = _safe_value(properties)
        # Stamped in the RECORDING process, beside harness. `source` used to be
        # read in the sending process from a module global, so whichever process
        # drained the spool named every event in it. flush() spreads per-event
        # properties last, so this now wins over any sender's default.
        properties.update(
            harness=_harness,
            source=_source_tag,
            plugin_version=memory_core.PLUGIN_VERSION,
            os=sys.platform,
            python_version=platform.python_version(),
        )
        # Assigned only when the digest is real. _scoped_digest returns "" when
        # the salt could not be persisted, and an empty property is worse than an
        # absent one: it survives the None filter below and reads as a value.
        if repo is not None:
            repo_hash = _scoped_digest(getattr(repo, "identity", ""))
            if repo_hash:
                properties["repo_hash"] = repo_hash
        if session_id:
            session_hash = _scoped_digest(session_id)
            if session_hash:
                properties["session_hash"] = session_hash
        line = json.dumps(
            {
                "event": f"{EVENT_PREFIX}.{event}",
                "uuid": str(uuid.uuid4()),
                "timestamp": memory_core.utc_now(),
                "properties": {
                    key: value for key, value in properties.items() if value is not None
                },
            },
            separators=(",", ":"),
            default=str,
        )
        spool.parent.mkdir(parents=True, exist_ok=True)
        with spool.open("a", encoding="utf-8") as handle:
            handle.write(line + "\n")
    except Exception:
        pass

def error_kind(exc: BaseException | str) -> str:
    """Coarse, content-free label for a failure, safe to send."""
    text = exc if isinstance(exc, str) else f"{type(exc).__name__}: {exc}"
    lowered = text.lower()
    if "timed out" in lowered or "timeout" in lowered:
        return "timeout"
    if "401" in lowered or "403" in lowered or "unauthor" in lowered or "forbidden" in lowered:
        return "auth"
    if "429" in lowered or "rate limit" in lowered:
        return "rate-limited"
    if any(code in lowered for code in ("500", "502", "503", "504")):
        return "server-error"
    if "400" in lowered or "422" in lowered:
        return "bad-request"
    if isinstance(exc, str):
        return "other"
    if isinstance(exc, urllib.error.URLError):
        return "network"
    return type(exc).__name__

def spawn_flush() -> bool:
    """Start the detached sender that drains the spool."""
    if not is_enabled():
        return False
    try:
        if not _spool_path().exists() and not any(
            memory_core.data_dir().glob("telemetry-*.sending")
        ):
            return False
        subprocess.Popen(
            [sys.executable, str(Path(__file__).resolve())],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            close_fds=True,
            **memory_core.detached_process_kwargs(),
        )
        return True
    except Exception:
        return False

def _claim_spool() -> Path | None:
    """Rename the spool aside so exactly one sender owns each batch."""
    directory = memory_core.data_dir()
    claim = directory / _claim_name()
    spool = _spool_path()
    try:
        spool.replace(claim)
        _touch(claim)
        return claim
    except OSError:
        pass
    return _claim_parked(directory)

def _sweep_debris(directory: Path) -> None:
    """Remove files nothing else will ever pick up again.

    *.partial is a temp file orphaned by a crash between write and rename.
    *.corrupt is a batch quarantined for undecodable content. No glob in this
    module matches either, so without this they accumulate on disk for the life
    of the install.

    Quarantined batches are kept far longer than debris: they are the only
    evidence left of events that could not be delivered, and someone diagnosing
    a report of missing telemetry has to be able to find one.
    """
    now = time.time()
    for debris in directory.glob("telemetry-*.partial"):
        try:
            if now - debris.stat().st_mtime > CLAIM_STALE_SECONDS:
                debris.unlink()
        except OSError:
            continue
    for quarantined in directory.glob("telemetry-*.corrupt"):
        try:
            if now - quarantined.stat().st_mtime > CLAIM_EXPIRY_SECONDS:
                quarantined.unlink()
        except OSError:
            continue
    # The same reasoning covers *.tmp. _write_identity and _install_salt both
    # create one and unlink it in a finally, which a SIGKILL skips, and no glob
    # in this module matches the leftovers either.
    for temporary in directory.glob("telemetry-*.tmp"):
        try:
            if now - temporary.stat().st_mtime > CLAIM_STALE_SECONDS:
                temporary.unlink()
        except OSError:
            continue

def _safe_mtime(path: Path) -> float:
    try:
        return path.stat().st_mtime
    except OSError:
        return 0.0

def _resolve_email(key: str) -> str:
    """Trade the API key for the account email so events join other Mem0 surfaces."""
    url = os.environ.get("MEM0_API_URL", memory_core.DEFAULT_API_URL).rstrip("/") + "/v1/ping/"
    request = urllib.request.Request(
        url, headers={"Authorization": f"Token {key}", "Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(request, timeout=SEND_TIMEOUT) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except Exception:
        return ""
    email = payload.get("user_email") if isinstance(payload, dict) else ""
    return email if isinstance(email, str) else ""

def _post(payload: dict[str, Any], url: str) -> bool:
    request = urllib.request.Request(
        url,
        data=json.dumps(payload, default=str).encode("utf-8"),
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(request, timeout=SEND_TIMEOUT):
            return True
    except Exception:
        return False

def _drain(claim: Path | None) -> tuple[int, bool]:
    """Post one claimed batch file, recording progress after every batch.

    Returns (events sent, whether everything was delivered).
    """
    if claim is None:
        return 0, True
    try:
        lines = claim.read_text(encoding="utf-8").splitlines()
    except ValueError:
        # UnicodeDecodeError from a torn write: the content is unrecoverable, so
        # quarantine rather than retry. flush() runs from a bare `finally:` in
        # flush_worker, so raising here also skips the handoff cleanup, and an
        # undecodable file would otherwise be re-read on every flush forever.
        # Reported as delivered because there is nothing left to deliver and the
        # rest of the run should continue.
        try:
            claim.replace(claim.with_suffix(".corrupt"))
        except OSError:
            try:
                claim.unlink()
            except OSError:
                pass
        return 0, True
    except OSError:
        # Could not read it, which is not the same as having nothing to send.
        # The file is left exactly where it is: a vanished or briefly unreadable
        # claim is retryable, and quarantining it here would discard events over
        # a transient filesystem error. Reported as undelivered so the run stops
        # instead of counting a batch nothing was posted from as delivered.
        return 0, False
    events = []
    for line in lines:
        try:
            value = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict) and value.get("event"):
            events.append(value)
    if not events:
        # Only delete when the file really is empty. A non-empty file that
        # parses to nothing is a torn write, and its contents are the unsent
        # remainder — deleting it is the data loss this PR exists to prevent.
        try:
            empty = claim.stat().st_size == 0
        except OSError:
            empty = True
        try:
            claim.replace(claim.with_suffix(".corrupt")) if not empty else claim.unlink()
        except OSError:
            pass
        return 0, True

    distinct_id, aliased_anonymous_id = resolve_distinct_id()
    if aliased_anonymous_id:
        _post(
            {
                "api_key": POSTHOG_API_KEY,
                "event": "$identify",
                "distinct_id": distinct_id,
                "properties": {
                    "$anon_distinct_id": aliased_anonymous_id,
                    "$lib": "posthog-python",
                },
            },
            POSTHOG_CAPTURE_URL,
        )

    sent = 0
    for start in range(0, len(events), BATCH_SIZE):
        chunk = events[start : start + BATCH_SIZE]
        batch = [
            {
                "event": event["event"],
                "distinct_id": distinct_id,
                # Carried through from record() so a resend can be collapsed.
                "uuid": event.get("uuid"),
                "timestamp": event.get("timestamp"),
                "properties": {
                    # Fallback only: events recorded by a build before source
                    # moved into record() have none of their own.
                    "source": _source_tag,
                    "language": "python",
                    "$process_person_profile": False,
                    "$lib": "posthog-python",
                    **(event.get("properties") or {}),
                },
            }
            for event in chunk
        ]
        if not _post({"api_key": POSTHOG_API_KEY, "batch": batch}, POSTHOG_BATCH_URL):
            # Keep only what has not been delivered, and release the lease.
            # Previously the whole file was kept and the retry re-posted every
            # batch, including the ones that had already arrived.
            _release_claim(claim, events[start:])
            return sent, False
        sent += len(chunk)
        # Record progress and refresh the lease after each successful batch, so
        # a crash repeats at most one batch instead of the entire file. If the
        # rewrite fails the claim still holds delivered events, so stop rather
        # than carry on as though progress were recorded — continuing is how the
        # duplicate delivery this PR fixes would come back.
        if not _rewrite_claim(claim, events[start + len(chunk) :]):
            _release_claim(claim, events[start + len(chunk) :])
            return sent, False
    return sent, True

def main() -> int:
    flush()
    return 0

integrations/antigravity-plugin/hooks/ad.source_code:
def _read_transcript(path: str) -> list[dict[str, str]]:
    messages = []
    try:
        with open(path, encoding="utf-8") as transcript:
            for line in transcript:
                try:
                    step = json.loads(line)
                except json.JSONDecodeError:
                    continue
                content = step.get("content")
                if not isinstance(content, str) or step.get("status") != "DONE":
                    continue
                if step.get("type") == "USER_INPUT":
                    match = re.search(r"<USER_REQUEST>\s*(.*?)\s*</USER_REQUEST>", content, re.DOTALL)
                    messages.append({"role": "user", "content": redact(match.group(1) if match else content).strip()})
                elif step.get("source") == "MODEL" and step.get("type") == "PLANNER_RESPONSE":
                    messages.append({"role": "assistant", "content": redact(content).strip()})
    except (OSError, TypeError):
        pass
    return messages

def _transcript_messages(path: str) -> tuple[str, str]:
    messages = _read_transcript(path)
    return tuple(next((m["content"] for m in reversed(messages) if m["role"] == role), "")
                 for role in ("user", "assistant"))

def _record_stop(store, payload):
    session_id = str(payload.get("session_id") or "unknown-session")
    repo = store.repo_for_session(session_id, payload.get("cwd"))
    path = str(payload.get("transcript_path") or "")
    messages = _read_transcript(path)
    if not messages:
        return hook_runner.default_record_stop(store, payload)
    with store.conn:
        store.conn.execute("BEGIN IMMEDIATE")
        previous = store.latest_event_payload(repo.identity, session_id, "assistant_stop")
        offset = previous.get("transcript_count", 0) if previous.get("transcript_path") == path else 0
        if not isinstance(offset, int) or not 0 <= offset <= len(messages):
            offset = 0
        if messages[offset:]:
            store.record_event(repo, session_id, "assistant_stop", {
                "transcript_messages": messages[offset:],
                "transcript_count": len(messages),
                "transcript_path": path,
            })
    return repo, session_id

def normalize(payload: dict) -> dict:
    value = dict(payload)
    value.setdefault("session_id", value.get("conversationId", ""))
    workspaces = value.get("workspacePaths") or []
    cwd = workspaces[0] if workspaces else os.environ.get("MEM0_CWD", "").strip()
    if cwd:
        value.setdefault("cwd", cwd)
    value.setdefault("transcript_path", value.get("transcriptPath", ""))
    prompt, assistant = _transcript_messages(value["transcript_path"])
    if prompt:
        value.setdefault("prompt", prompt)
    if assistant:
        value.setdefault("last_assistant_message", assistant)
    tool_call = value.get("toolCall") or {}
    if isinstance(tool_call, dict):
        value.setdefault("tool_name", tool_call.get("name", ""))
        value.setdefault("tool_input", tool_call.get("args", {}))
    if value.get("error"):
        value.setdefault("tool_response", value["error"])
    return value

def main() -> int:
    if len(sys.argv) != 2 or sys.argv[1] not in {"PreInvocation", "PostToolUse", "Stop"}:
        return 2
    event = sys.argv[1]
    try:
        raw = json.load(sys.stdin)
    except (json.JSONDecodeError, OSError):
        raw = {}
    payload = normalize(raw if isinstance(raw, dict) else {})
    if not payload.get("cwd"):
        output = {"injectSteps": []} if event == "PreInvocation" else {}
        if event == "Stop":
            output = {"decision": "allow"}
        print(json.dumps(output))
        return 0
    configure_harness("antigravity", data_dir_name="antigravity-plugin", source_tag="antigravity_plugin")
    telemetry.init(harness="antigravity", source_tag="ANTIGRAVITY_PLUGIN")
    if event == "PreInvocation":
        if payload.get("invocationNum") != 0:
            print(json.dumps({"injectSteps": []}))
            return 0
        _run_shared(["session-start"], payload)
        result, output = _run_shared(["user-prompt"], payload)
        context = ""
        for line in output.splitlines():
            try:
                context = json.loads(line)["hookSpecificOutput"]["additionalContext"]
            except (json.JSONDecodeError, KeyError, TypeError):
                continue
        print(json.dumps({"injectSteps": [{"ephemeralMessage": context}] if context else []}))
        return result
    action = {
        "PostToolUse": ["post-tool-failure" if payload.get("error") else "post-tool"],
        "Stop": ["flush", "--reason", "session-end"],
    }[event]
    result, _ = _run_shared(action, payload)
    print(json.dumps({"decision": "allow"} if event == "Stop" else {}))
    return result

integrations/claude-code-plugin/adapters.source_code:
def _sidekick_start(store, hook_input):
    context = record_subagent_start(store, {"agent_type": "mem0:sidekick", **hook_input})
    if context:
        return {
            "hookSpecificOutput": {
                "hookEventName": "SubagentStart",
                "additionalContext": context,
            },
        }

def _message_content_text(content: Any) -> str:
    """Return visible text from one Claude transcript message."""
    if isinstance(content, str):
        return redact(content).strip()
    if not isinstance(content, list):
        return ""
    parts = []
    for block in content:
        if not isinstance(block, dict) or block.get("type") != "text":
            continue
        text = redact(block.get("text", "")).strip()
        if text:
            parts.append(text)
    return "\n\n".join(parts)

def _transcript_rows(
    path: str, offset: int = 0
) -> tuple[list[dict[str, Any]], int, bool]:
    """Parse transcript rows from a byte offset, returning rows, end offset, and whether the offset was honored."""
    if not path:
        return [], 0, False
    rows = []
    try:
        resolved = Path(path).expanduser()
        if not 0 <= offset <= resolved.stat().st_size:
            offset = 0
        end = offset
        with resolved.open("rb") as handle:
            handle.seek(offset)
            for line in handle:
                if not line.endswith(b"\n"):
                    break
                end += len(line)
                try:
                    row = json.loads(line.decode("utf-8", errors="replace"))
                except json.JSONDecodeError:
                    continue
                if isinstance(row, dict) and row.get("uuid"):
                    rows.append(row)
    except OSError:
        return [], offset, False
    return rows, end, offset > 0

def _active_transcript_chain(
    rows: list[dict[str, Any]], session_id: str
) -> list[dict[str, Any]]:
    """Follow the current Claude conversation branch from its latest record."""
    by_uuid = {str(row["uuid"]): row for row in rows if row.get("uuid")}
    leaf = next(
        (
            row
            for row in reversed(rows)
            if not row.get("isSidechain")
            and str(row.get("sessionId") or "") == session_id
        ),
        None,
    )
    if leaf is None:
        return []

    chain = []
    seen = set()
    current = leaf
    while current is not None:
        uuid = str(current.get("uuid") or "")
        if not uuid or uuid in seen:
            break
        seen.add(uuid)
        chain.append(current)
        current = by_uuid.get(str(current.get("parentUuid") or ""))
    chain.reverse()
    return chain

def _human_prompt_text(row: dict[str, Any]) -> str:
    if row.get("type") != "user":
        return ""
    origin = row.get("origin") or {}
    if isinstance(origin, dict) and origin.get("kind") not in {None, "human"}:
        return ""
    message = row.get("message") or {}
    content = message.get("content") if isinstance(message, dict) else None
    if not isinstance(content, str):
        return ""
    text = redact(content).strip()
    if text.startswith("<!-- attach -->"):
        text = text.removeprefix("<!-- attach -->").strip()
    ignored_prefixes = (
        "<local-command-caveat>",
        "<local-command-stdout>",
        "<local-command-stderr>",
        "<command-name>",
        "<system-reminder>",
        "<task-notification>",
    )
    return "" if text.startswith(ignored_prefixes) else text

def _xml_value(text: str, tag: str) -> str:
    match = re.search(fr"<{tag}>(.*?)</{tag}>", text, re.DOTALL)
    return html.unescape(match.group(1).strip()) if match else ""

def _agent_assignment(tool_input: dict[str, Any]) -> str:
    prompt = redact(tool_input.get("prompt", "")).strip()
    if not prompt:
        return ""
    agent_type = redact(tool_input.get("subagent_type", "agent")).strip() or "agent"
    description = redact(tool_input.get("description", "")).strip()
    heading = f"Subagent assignment ({agent_type}"
    if description:
        heading += f": {description}"
    return f"{heading}):\n{prompt}"

def _agent_response(tool_input: dict[str, Any], result: str) -> str:
    result = redact(result).strip()
    if not result or result.startswith("Async agent launched successfully."):
        return ""
    agent_type = redact(tool_input.get("subagent_type", "agent")).strip() or "agent"
    description = redact(tool_input.get("description", "")).strip()
    heading = f"Subagent response ({agent_type}"
    if description:
        heading += f": {description}"
    return f"{heading}):\n{result}"

def transcript_extraction_messages(
    transcript_path: str,
    session_id: str,
    *,
    previous_leaf_uuid: str = "",
    prompt_hint: str = "",
    fallback_assistant_message: str = "",
    label_final_response: bool = False,
    start_offset: int = 0,
) -> tuple[list[dict[str, str]], str, int]:
    """Read the meaningful part of the current Claude exchange."""
    rows, end_offset, resumed = _transcript_rows(transcript_path, start_offset)
    chain = _active_transcript_chain(rows, session_id)
    if not chain:
        if resumed:
            return [], previous_leaf_uuid, end_offset
        fallback = redact(fallback_assistant_message).strip()
        return (
            ([{"role": "assistant", "content": f"Main Claude response:\n{fallback}"}]
             if fallback
             else []),
            "",
            end_offset,
        )

    leaf_uuid = str(chain[-1].get("uuid") or "")
    if previous_leaf_uuid and leaf_uuid == previous_leaf_uuid:
        return [], leaf_uuid, end_offset
    start = 0
    if previous_leaf_uuid:
        for index, row in enumerate(chain):
            if str(row.get("uuid") or "") == previous_leaf_uuid:
                start = index + 1
                break
        else:
            previous_leaf_uuid = ""
    if not previous_leaf_uuid and not resumed:
        prompt_hint = redact(prompt_hint).strip()
        candidates = [
            index
            for index, row in enumerate(chain)
            if _human_prompt_text(row)
            and (
                not prompt_hint
                or _human_prompt_text(row) == prompt_hint
            )
        ]
        task_notifications = [
            index
            for index, row in enumerate(chain)
            if isinstance((row.get("message") or {}).get("content"), str)
            and (row.get("message") or {})["content"].startswith("<task-notification>")
        ]
        if candidates:
            start = candidates[-1]
        elif task_notifications:
            start = task_notifications[-1]

    tool_uses: dict[str, tuple[str, dict[str, Any]]] = {}
    for row in chain:
        message = row.get("message") or {}
        content = message.get("content") if isinstance(message, dict) else None
        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, dict) or block.get("type") != "tool_use":
                continue
            tool_id = str(block.get("id") or "")
            tool_input = block.get("input") or {}
            if tool_id and isinstance(tool_input, dict):
                tool_uses[tool_id] = (str(block.get("name") or ""), tool_input)

    output: list[dict[str, str]] = []

    def append(role: str, content: str) -> None:
        content = redact(content).strip()
        if content:
            output.append({"role": role, "content": content})

    for row in chain[start:]:
        message = row.get("message") or {}
        if not isinstance(message, dict):
            continue
        role = str(message.get("role") or "")
        content = message.get("content")

        if role == "user" and isinstance(content, str):
            if content.startswith("<task-notification>"):
                if _xml_value(content, "status") != "completed":
                    continue
                tool_id = _xml_value(content, "tool-use-id")
                tool = tool_uses.get(tool_id)
                result = _xml_value(content, "result")
                if tool and tool[0] == "Agent" and result:
                    assignment = _agent_assignment(tool[1])
                    response = _agent_response(tool[1], result)
                    append("assistant", assignment)
                    append("assistant", response)
                continue
            human = _human_prompt_text(row)
            if human:
                append("user", human)
            continue

        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, dict):
                continue
            block_type = block.get("type")
            if role == "assistant" and block_type == "text":
                append("assistant", str(block.get("text") or ""))
                continue
            if role != "user" or block_type != "tool_result":
                continue

            tool_id = str(block.get("tool_use_id") or "")
            tool = tool_uses.get(tool_id)
            if not tool:
                continue
            name, tool_input = tool
            result = _tool_result_text(block)
            failed = bool(block.get("is_error"))
            if name == "Agent" and not failed:
                response = _agent_response(tool_input, result)
                if response:
                    append("assistant", _agent_assignment(tool_input))
                    append("assistant", response)
            elif name == "AskUserQuestion" and result and not failed:
                append("user", f"User answers to Claude's questions:\n{result}")
            elif name == "ExitPlanMode" and not failed:
                plan = redact(tool_input.get("plan", "")).strip()
                if plan:
                    append("assistant", f"Approved implementation plan:\n{plan}")

    fallback = redact(fallback_assistant_message).strip()
    if fallback:
        labeled = f"Main Claude response:\n{fallback}"
        for message in reversed(output):
            if message["role"] == "assistant" and message["content"] == fallback:
                message["content"] = labeled
                break
        else:
            append("assistant", labeled)
    elif label_final_response:
        last_message = chain[-1].get("message") or {}
        last_content = (
            last_message.get("content") if isinstance(last_message, dict) else None
        )
        final_parts = [
            redact(block.get("text", "")).strip()
            for block in (last_content if isinstance(last_content, list) else [])
            if isinstance(block, dict)
            and block.get("type") == "text"
            and redact(block.get("text", "")).strip()
        ]
        for start in range(len(output) - len(final_parts), -1, -1):
            candidate = output[start : start + len(final_parts)]
            if final_parts and [item["content"] for item in candidate] == final_parts:
                candidate[0]["content"] = (
                    f"Main Claude response:\n{candidate[0]['content']}"
                )
                break
    return output, leaf_uuid, end_offset

