def main() -> int:
    if len(sys.argv) != 2:
        return 2
    handoff_path = Path(sys.argv[1])
    os.environ["MEM0_CODE_HANDOFF_PATH"] = str(handoff_path)
    harness = os.environ.get("MEM0_PLUGIN_HARNESS")
    if harness:
        source_tag = os.environ.get("MEM0_PLUGIN_SOURCE_TAG", "")
        configure_harness(
            harness,
            env_prefix=os.environ.get("MEM0_PLUGIN_ENV_PREFIX", ""),
            data_dir_name=os.environ.get("MEM0_PLUGIN_DATA_DIR_NAME", ""),
            source_tag=source_tag,
        )
        telemetry.init(harness=harness, source_tag=source_tag.upper())
    completed = False
    try:
        payload = json.loads(handoff_path.read_text(encoding="utf-8"))
        delay = float(payload.get("delay_seconds") or 0)
        if delay > 0:
            payload.pop("delay_seconds", None)
            temporary = handoff_path.with_suffix(f".{os.getpid()}.tmp")
            try:
                temporary.write_text(json.dumps(payload), encoding="utf-8")
                temporary.replace(handoff_path)
            finally:
                temporary.unlink(missing_ok=True)
            time.sleep(delay)
            if not handoff_path.exists():
                return 0
        hook_input = payload.get("hook_input") or {}
        reason = str(payload.get("reason") or "checkpoint")
        wait_for_inflight = bool(payload.get("wait_for_inflight"))
        store = EvidenceStore()
        try:
            if wait_for_inflight:
                session_id = str(
                    hook_input.get("session_id") or "unknown-session"
                )
                repo = store.repo_for_session(session_id, hook_input.get("cwd"))
                deadline = time.monotonic() + float(
                    os.environ.get("MEM0_CODE_EXTRACTION_WAIT_SECONDS", "120")
                )
                while (
                    store.has_inflight_flush(repo.identity, session_id)
                    and time.monotonic() < deadline
                ):
                    touch_handoff_heartbeat()
                    time.sleep(0.25)
            # Hooks capture the conversation before handoff; the worker only flushes it.
            result = checkpoint_session(store, hook_input, reason)
            print(json.dumps(result, sort_keys=True), flush=True)
            completed = result.get("status") in {
                "semantic-succeeded",
                "explicitly-stored",
                "nothing-to-flush",
            }
        finally:
            store.close()
        return 0
    finally:
        telemetry.flush()
        if completed:
            try:
                handoff_path.unlink()
            except OSError:
                pass
        elif handoff_path.suffix == ".running":
            try:
                handoff_path.replace(handoff_path.with_suffix(".json"))
            except OSError:
                pass

