function detectAppId(cwd: string): string {
  try {
    const root = execFileSync("git", ["rev-parse", "--show-toplevel"], {
      cwd,
      encoding: "utf-8",
      timeout: 3000,
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    return path.basename(root);
  } catch {
    return path.basename(cwd);
  }
}

function detectRunId(sessionFile: string | undefined): string {
  if (!sessionFile) return "unknown";
  return crypto.createHash("sha256").update(sessionFile).digest("hex").slice(0, 12);
}

function resolveSearchFilters(
  scope: Scope,
  ctx: ScopeContext,
): Record<string, string> {
  return scopeSearchFilters(scope, ctx);
}

function resolveAddParams(
  scope: Scope,
  ctx: ScopeContext,
): Record<string, string> {
  return scopeAddParams(scope, ctx);
}

interface MemoryResult {
  message?: string;
  eventId?: string;
  status?: string;
}

function truncateOutput(text: string): string {
  const lines = text.split("\n");
  if (lines.length <= MAX_OUTPUT_LINES && text.length <= MAX_OUTPUT_BYTES) {
    return text;
  }

  const kept = lines.slice(0, MAX_OUTPUT_LINES);
  let result = kept.join("\n");
  if (result.length > MAX_OUTPUT_BYTES) {
    result = result.slice(0, MAX_OUTPUT_BYTES);
  }

  const dropped = lines.length - kept.length;
  if (dropped > 0 || text.length > MAX_OUTPUT_BYTES) {
    result += `\n\n[Output truncated: showing ${kept.length} of ${lines.length} lines]`;
  }
  return result;
}

interface ToolParams {
  action: "search" | "add" | "get_all" | "update" | "delete" | "delete_all";
  query?: string;
  content?: string;
  memory_id?: string;
  scope?: Scope;
}

function buildToolExecute(
  mem0: MemoryClient,
  scopeCtx: ScopeContext,
  defaultScope: Scope,
) {
  return async (params: ToolParams, signal?: AbortSignal) => {
    const scope = resolveToolScope(params.scope, defaultScope);

    switch (params.action) {
      case "search": {
        if (signal?.aborted) throw new Error("Cancelled");
        if (!params.query) throw new Error("query is required for search");
        const filters = resolveSearchFilters(scope, scopeCtx);
        const result = await mem0.search(params.query, { filters });
        const memories = result.results ?? [];
        return {
          content: [{ type: "text" as const, text: truncateOutput(formatMemoryList(memories)) }],
          details: { matchCount: memories.length },
        };
      }

      case "add": {
        if (signal?.aborted) throw new Error("Cancelled");
        if (!params.content) throw new Error("content is required for add");
        const addParams = resolveAddParams(scope, scopeCtx);
        const result = await mem0.add(
          [{ role: "user", content: params.content }],
          { ...addParams, customCategories: DEFAULT_CUSTOM_CATEGORIES },
        );
        const res = result as MemoryResult;
        const msg = res.message ?? "Memory stored.";
        return {
          content: [{ type: "text" as const, text: msg }],
          details: { eventId: res.eventId ?? null, status: res.status ?? null },
        };
      }

      case "get_all": {
        if (signal?.aborted) throw new Error("Cancelled");
        const filters = resolveSearchFilters(scope, scopeCtx);
        const result = await mem0.getAll({ filters });
        const memories = result.results ?? [];
        return {
          content: [{ type: "text" as const, text: truncateOutput(formatMemoryList(memories)) }],
          details: { totalCount: result.count ?? memories.length },
        };
      }

      case "update": {
        if (signal?.aborted) throw new Error("Cancelled");
        if (!params.memory_id) throw new Error("memory_id is required for update");
        if (!params.content) throw new Error("content is required for update");
        const memoryId = normalizeMemoryId(params.memory_id);
        const updateResult = await mem0.update(memoryId, { text: params.content });
        const res = updateResult as MemoryResult;
        return {
          content: [{ type: "text" as const, text: res.status ?? "Memory updated." }],
          details: { memoryId },
        };
      }

      case "delete": {
        if (signal?.aborted) throw new Error("Cancelled");
        if (!params.memory_id) throw new Error("memory_id is required for delete");
        const result = await mem0.delete(normalizeMemoryId(params.memory_id));
        return {
          content: [{ type: "text" as const, text: result.message ?? "Memory deleted." }],
          details: {},
        };
      }

      case "delete_all": {
        if (signal?.aborted) throw new Error("Cancelled");
        const delParams = resolveAddParams(scope, scopeCtx);
        const result = await mem0.deleteAll(delParams);
        return {
          content: [{ type: "text" as const, text: result.message ?? "All memories deleted." }],
          details: {},
        };
      }
    }
  };
}

function registerMemoryTool(
  pi: ExtensionAPI,
  mem0: MemoryClient,
  config: Mem0Config,
  getScopeCtx: () => ScopeContext,
  telemetryCtx?: { apiKey?: string },
): void {
  pi.registerTool({
    name: "mem0_memory",
    label: "Mem0 Memory",
    description:
      `Search, add, update, and manage persistent semantic memories powered by Mem0. Memories persist across sessions and devices. Use action "search" ${SEARCH_WHEN}. Output is truncated to 200 lines / 50KB.`,
    promptSnippet: "Semantic memory search and storage via Mem0",
    promptGuidelines: [
      `Use mem0_memory with action "search" ${SEARCH_WHEN}`,
      'Use mem0_memory with action "add" to save important facts, preferences, goals, decisions, or lessons the user shares',
      'Use mem0_memory with action "update" to modify an existing memory — requires memory_id and content. Preserves the memory ID',
      "Always use the default project scope unless the user EXPLICITLY asks to search across all projects — only after the user selects /mem0-scope global use scope \"global\"",
      "Do NOT pass scope at all for normal queries — omitting it uses the project default automatically",
    ],
    parameters: Type.Object({
      action: StringEnum(
        [
          "search",
          "add",
          "get_all",
          "update",
          "delete",
          "delete_all",
        ] as const,
        {
          description:
            "Memory operation to run: \"search\" (semantic recall of earlier work in this repository), \"add\" (save a new fact/preference/decision), \"get_all\" (list everything in scope, no query needed), \"update\" (replace an existing memory's text by id), \"delete\" (remove one memory by id), \"delete_all\" (wipe every memory in the scope -- destructive, only on explicit request).",
        },
      ),
      query: Type.Optional(
        Type.String({
          description:
            `Search text -- required for action "search". ${SEARCH_QUERY_DESCRIPTION}`,
        }),
      ),
      content: Type.Optional(
        Type.String({
          description:
            "Memory text -- required for action \"add\" (the fact to store) and \"update\" (the replacement text).",
        }),
      ),
      memory_id: Type.Optional(
        Type.String({
          description:
            "Target memory's ID -- required for \"update\" and \"delete\". Use an ID returned by a prior \"search\" or \"get_all\".",
        }),
      ),
      scope: Type.Optional(
        StringEnum(["project", "session", "global"] as const, {
          description:
            "Where to read/write: \"project\" (default -- this repo), \"session\" (this run only), or \"global\" (across ALL projects; only when the user explicitly wants cross-project recall). Omit for normal queries.",
        }),
      ),
    }),
    async execute(toolCallId, params, signal, onUpdate, ctx) {
      const scopeCtx = getScopeCtx();
      const exec = buildToolExecute(mem0, scopeCtx, config.defaultScope);
      const start = Date.now();
      try {
        const result = await exec(params as ToolParams, signal);
        const details = (result as any).details ?? {};
        captureToolEvent((params as ToolParams).action, {
          success: true,
          latency_ms: Date.now() - start,
          result_count: details.matchCount ?? details.totalCount ?? undefined,
        }, telemetryCtx);
        return result;
      } catch (err) {
        captureToolEvent((params as ToolParams).action, {
          success: false,
          latency_ms: Date.now() - start,
          error_type: err instanceof Error ? err.name : "unknown",
        }, telemetryCtx);
        throw err;
      }
    },
  });
}

integrations/pi-agent-plugin/src/telemet.source_code:
function findEvent(name: string): Record<string, unknown> | undefined {
  return _getEventQueue().find((e) => (e as Record<string, unknown>).event === name) as
    | Record<string, unknown>
    | undefined;
}

function anonymousId(): string {
  if (cachedAnonymousId) return cachedAnonymousId;
  try {
    const stored = JSON.parse(fs.readFileSync(TELEMETRY_ID_PATH, "utf-8")).anonymousId;
    if (typeof stored === "string" && stored) return (cachedAnonymousId = stored);
  } catch {
    // First run or unreadable identity file.
  }
  const created = `pi-mem0-anon-${randomUUID().replace(/-/g, "")}`;
  try {
    fs.mkdirSync(CONFIG_DIR, { recursive: true });
    fs.writeFileSync(TELEMETRY_ID_PATH, JSON.stringify({ anonymousId: created }), "utf-8");
  } catch {
    // An unwritable config directory must not break the plugin.
  }
  return (cachedAnonymousId = created);
}

function distinctId(apiKey?: string): string {
  return apiKey ? createHash("sha256").update(apiKey).digest("hex") : anonymousId();
}

function previousAnonymousId(id: string): string | undefined {
  if (identified || id.startsWith("pi-mem0-anon-")) return undefined;
  identified = true;
  try {
    const stored = JSON.parse(fs.readFileSync(TELEMETRY_ID_PATH, "utf-8")).anonymousId;
    fs.unlinkSync(TELEMETRY_ID_PATH);
    cachedAnonymousId = undefined;
    return typeof stored === "string" && stored ? stored : undefined;
  } catch {
    return undefined;
  }
}

function captureEvent(
  eventName: string,
  properties: Record<string, unknown> = {},
  context?: { apiKey?: string },
): void {
  currentDistinctId = distinctId(context?.apiKey);
  const anonymous = previousAnonymousId(currentDistinctId);
  if (anonymous) telemetry.capture("$identify", { $anon_distinct_id: anonymous });
  telemetry.capture(eventName, properties);
}

function captureToolEvent(
  action: string,
  properties: Record<string, unknown> = {},
  context?: { apiKey?: string },
): void {
  captureEvent("pi.tool.mem0_memory", { action, ...properties }, context);
}

function captureCommandEvent(
  command: string,
  properties: Record<string, unknown> = {},
  context?: { apiKey?: string },
): void {
  captureEvent(`pi.command.${command}`, properties, context);
}

function _resetForTesting(): void {
  telemetry.resetForTesting();
  cachedAnonymousId = undefined;
  currentDistinctId = "";
  identified = false;
}

