interface MultimodalContent {
    type: 'text' | 'image_url' | 'mdx_url' | 'pdf_url';
    text?: string;
    image_url?: {
        url: string;
    };
    mdx_url?: {
        url: string;
    };
    pdf_url?: {
        url: string;
    };
}

interface FileContent {
    type: 'file';
    data: string; // fileDataUrl
    mediaType: string; // e.g., 'application/pdf', 'text/markdown', 'image/jpeg'
}

interface Message {
    role: string;
    content: string | MultimodalContent | Array<MultimodalContent>;
}

flattenPrompt = (prompt: LanguageModelV3Prompt) => {
    try {
        return prompt.map((part) => {
            if (part.role === "user") {
                if (typeof part.content === 'string') {
                    return part.content;
                } else if (Array.isArray(part.content)) {
                    return part.content
                        .filter((obj) => obj.type === 'text')
                        .map((obj) => obj.text)
                        .join(" ");
                } else if (part.content && typeof part.content === 'object' && 'type' in part.content) {
                    const content = part.content as any;
                    if (content.type === 'text' && content.text) {
                        return content.text;
                    } else if (content.type === 'file') {
                        if (content.mediaType === 'application/pdf') {
                            return '[PDF document]';
                        } else if (content.mediaType === 'text/markdown' || content.mediaType === 'application/mdx') {
                            return '[Markdown document]';
                        } else if (content.mediaType && content.mediaType.startsWith('image/')) {
                            return '[Image]';
                        } else {
                            return '[File attachment]';
                        }
                    }
                }
                return "[multimodal content]";
            }
            return "";
        }).join(" ");
    } catch (error) {
        console.error("Error in flattenPrompt:", error);
        return "";
    }
}

convertToMem0Format = (messages: LanguageModelV3Prompt) => {
    try {
        return messages.flatMap((message: any) => {
            try {
                if (typeof message.content === 'string') {
                    return {
                        role: message.role,
                        content: message.content,
                    };
                }
                else if (Array.isArray(message.content)) {
                    return message.content.map((obj: any) => {
                        try {
                            if (obj.type === "text") {
                                return {
                                    role: message.role,
                                    content: obj.text,
                                };
                            } else if (obj.type === "file") {
                                if (obj.mediaType === "application/pdf") {
                                    return {
                                        role: message.role,
                                        content: {
                                            type: "pdf_url",
                                            pdf_url: {
                                                url: obj.data
                                            }
                                        }
                                    };
                                } else if (obj.mediaType === "text/markdown" || obj.mediaType === "application/mdx") {
                                    return {
                                        role: message.role,
                                        content: {
                                            type: "mdx_url",
                                            mdx_url: {
                                                url: obj.data
                                            }
                                        }
                                    };
                                } else if (obj.mediaType && obj.mediaType.startsWith("image/")) {
                                    return {
                                        role: message.role,
                                        content: {
                                            type: "image_url",
                                            image_url: {
                                                url: obj.data
                                            }
                                        }
                                    };
                                }
                            } else if (obj.type === "image_url" || obj.type === "image") {
                                return {
                                    role: message.role,
                                    content: {
                                        type: "image_url",
                                        image_url: {
                                            url: obj.image_url?.url || obj.image?.url || obj.url
                                        }
                                    }
                                };
                            } else if (obj.type === "mdx_url" || obj.type === "mdx") {
                                return {
                                    role: message.role,
                                    content: {
                                        type: "mdx_url",
                                        mdx_url: {
                                            url: obj.mdx_url?.url || obj.mdx?.url || obj.url
                                        }
                                    }
                                };
                            } else if (obj.type === "pdf_url" || obj.type === "pdf") {
                                return {
                                    role: message.role,
                                    content: {
                                        type: "pdf_url",
                                        pdf_url: {
                                            url: obj.pdf_url?.url || obj.pdf?.url || obj.url
                                        }
                                    }
                                };
                            }
                            return null;
                        } catch (error) {
                            console.error("Error processing content object:", error);
                            return null;
                        }
                    }).filter((item: null) => item !== null);
                } else {
                    const obj = message.content;
                    if (obj.type === "text") {
                        return {
                            role: message.role,
                            content: obj.text,
                        };
                    } else if (obj.type === "file") {
                        if (obj.mediaType === "application/pdf") {
                            return {
                                role: message.role,
                                content: {
                                    type: "pdf_url",
                                    pdf_url: {
                                        url: obj.data
                                    }
                                }
                            };
                        } else if (obj.mediaType === "text/markdown" || obj.mediaType === "application/mdx") {
                            return {
                                role: message.role,
                                content: {
                                    type: "mdx_url",
                                    mdx_url: {
                                        url: obj.data
                                    }
                                }
                            };
                        } else if (obj.mediaType && obj.mediaType.startsWith("image/")) {
                            return {
                                role: message.role,
                                content: {
                                    type: "image_url",
                                    image_url: {
                                        url: obj.data
                                    }
                                }
                            };
                        }
                    } else if (obj.type === "image_url" || obj.type === "image") {
                        return {
                            role: message.role,
                            content: {
                                type: "image_url",
                                image_url: {
                                    url: obj.image_url?.url || obj.image?.url || obj.url
                                }
                            }
                        };
                    } else if (obj.type === "mdx_url" || obj.type === "mdx") {
                        return {
                            role: message.role,
                            content: {
                                type: "mdx_url",
                                mdx_url: {
                                    url: obj.mdx_url?.url || obj.mdx?.url || obj.url
                                }
                            }
                        };
                    } else if (obj.type === "pdf_url" || obj.type === "pdf") {
                        return {
                            role: message.role,
                            content: {
                                type: "pdf_url",
                                pdf_url: {
                                    url: obj.pdf_url?.url || obj.pdf?.url || obj.url
                                }
                            }
                        };
                    }
                    return null;
                }
            } catch (error) {
                console.error("Error processing message:", error);
                return [];
            }
        });
    } catch (error) {
        console.error("Error in convertToMem0Format:", error);
        return [];
    }
}

searchInternalMemories = async (query: string, config?: Mem0ConfigSettings, top_k: number = 10) => {
