def _format_conversation_history(messages):
    """Format message dicts into 'role: content' lines with truncation."""
    if not messages:
        return ""
    result = ""
    for msg in messages:
        role = msg.get("role", "")
        content = msg.get("message") or msg.get("content", "")
        if role and content:
            result += f"{role}: {_truncate_content(content)}\n"
    return result

