def _json_path(metadata_key: str) -> str:
    _validate_metadata_key(metadata_key)

    path_parts: List[str] = []
    for part in metadata_key.split("."):
        if part.endswith("[*]"):
            path_parts.append(f'."{part[:-3]}"[*]')
        else:
            path_parts.append(f'."{part}"')
    return "".join(path_parts)

