def _is_datetime_range(range_kwargs: dict) -> bool:
    """Check if all values in range kwargs are ISO datetime strings."""
    return all(
        isinstance(v, str) and Qdrant._ISO_DATETIME_RE.match(v)
        for v in range_kwargs.values()
    )

