    const query = new URLSearchParams(snakeOptions).toString();
    return this._fetchWithErrorHandling(
      `${this.host}/v1/memories/${encodePathSegment(memoryId)}/${query ? `?${query}` : ""}`,
      {
        method: "DELETE",
