function formatConversationHistory(
  messages?: Array<{ role: string; content: string }>,
): string {
  if (!messages || messages.length === 0) return "";
  let result = "";
  for (const msg of messages) {
    const role = msg.role ?? "";
    const content = msg.content ?? "";
    if (role && content) {
      result += `${role}: ${truncateContent(content)}\n`;
    }
  }
  return result;
}

