    await emitNoticeDisplayed(instance, {
      notice_id: FIRST_RUN_NOTICE_ID,
      notice_type: LOG_LINE_NOTICE_TYPE,
      flag_key: NOTICE_FLAG_KEY,
      variant: flagEvaluation.variant,
