    method: "notice_displayed",
    api_host: instance.host,
    timestamp: new Date().toISOString(),
    client_version: version,
    client_source: "nodejs",
    ...properties,
    sample_rate: 1.0,
  };

  await telemetry.captureEvent(
    instance.telemetryId,
    NOTICE_EVENT_NAME,
    eventData,
  );
}

