  /**
   * Retrieve a vector by ID
   */
  async get(vectorId: string): Promise<VectorStoreResult | null> {
    await this.initialize();
    try {
      const result = await this.searchClient.getDocument(vectorId);
      const payloadStr = result.payload as string;
