function buildDatabricksAuthorizationDetails(
  indexName: string,
  operation: "ReadVectorIndex" | "WriteVectorIndex",
): string {
  return JSON.stringify([
    {
      type: "unity_catalog_permission",
      securable_type: "table",
      securable_object_name: indexName,
      operation,
    },
  ]);
