}

function buildWhereClause(
  filters?: SearchFilters,
): [string, Record<string, any>] {
  if (!filters || Object.keys(filters).length === 0) {
    return ["", {}];
  }
  const binds: Record<string, any> = {};
  return [`WHERE ${buildFilterGroup(filters, binds)}`, binds];
}

