interface ValkeyClient {
  call: (...args: (string | number | Buffer)[]) => Promise<unknown>;
  hset: (key: string, data: Record<string, string | Buffer>) => Promise<number>;
  hgetall: (key: string) => Promise<Record<string, string>>;
  exists: (key: string) => Promise<number>;
  del: (key: string) => Promise<number>;
  get: (key: string) => Promise<string | null>;
  set: (key: string, value: string) => Promise<"OK">;
  quit: () => Promise<"OK">;
  on: (event: string, listener: (...args: any[]) => void) => void;
}

function escapeTagValue(value: unknown): string {
  return String(value).replace(
    /([,.<>{}\[\]"':;!@#$%^&*()\-+=~|/\\\s])/g,
    "\\$1",
  );
}

function toSnakeCase(obj: Record<string, any>): Record<string, any> {
  if (typeof obj !== "object" || obj === null) return obj;
  return Object.fromEntries(
    Object.entries(obj).map(([key, value]) => [
      key.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`),
      value,
    ]),
  );
}

interface ValkeySearchDoc {
  memory_id?: string;
  hash?: string;
  memory?: string;
  created_at?: string;
  updated_at?: string;
  agent_id?: string;
  run_id?: string;
  user_id?: string;
  metadata?: string;
  vector_score?: string;
}

function parseFtSearchResults(result: unknown[]): {
  total: number;
  docs: ValkeySearchDoc[];
} {
  const total = Number(result[0]) || 0;
  const docs: ValkeySearchDoc[] = [];
  for (let i = 1; i < result.length; i += 2) {
    const fields = result[i + 1] as string[];
    const doc: ValkeySearchDoc = {};
    for (let j = 0; j < fields.length; j += 2) {
      const key = fields[j] as keyof ValkeySearchDoc;
      (doc as Record<string, string>)[key] = fields[j + 1] as string;
    }
    docs.push(doc);
  }
  return { total, docs };
}

function parseValkeyUrl(url: string): {
  host: string;
  port: number;
  username?: string;
  password?: string;
} {
  const normalized = url.replace(/^valkey:\/\//, "redis://");
  const parsed = new URL(normalized);
  return {
    host: parsed.hostname,
    port: parsed.port ? parseInt(parsed.port, 10) : 6379,
    username: parsed.username ? decodeURIComponent(parsed.username) : undefined,
    password: parsed.password ? decodeURIComponent(parsed.password) : undefined,
  };
}

function formatTimestamp(timestamp: number, timezone: string = "UTC"): string {
  const date = new Date(timestamp * 1000);
  if (timezone === "UTC") {
    return date.toISOString();
  }
  // Mirror Python's datetime.fromtimestamp(ts, tz).isoformat(): render the
  // instant as an ISO-8601 string carrying the target IANA timezone's offset.
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(date);
  const get = (type: string) =>
    parts.find((part) => part.type === type)?.value ?? "00";
  const yyyy = get("year");
  const MM = get("month");
  const dd = get("day");
  const HH = get("hour");
  const mm = get("minute");
  const ss = get("second");
  const asIfUtc = Date.UTC(
    Number(yyyy),
    Number(MM) - 1,
    Number(dd),
    Number(HH),
    Number(mm),
    Number(ss),
  );
  const offsetMinutes = Math.round((asIfUtc - date.getTime()) / 60000);
  const sign = offsetMinutes >= 0 ? "+" : "-";
  const absOffset = Math.abs(offsetMinutes);
  const offHH = String(Math.floor(absOffset / 60)).padStart(2, "0");
  const offMM = String(absOffset % 60).padStart(2, "0");
  return `${yyyy}-${MM}-${dd}T${HH}:${mm}:${ss}${sign}${offHH}:${offMM}`;
}

