        this.indexName,
        {
          account_id: this.accountId,
          vector: query,
          filter: filters,
          returnMetadata: "all",
          topK: topK,
        },
      );

      return (
        (result?.matches?.map((match) => ({
          id: match.id,
          payload: match.metadata,
