    return randomUserId;
  }

  async setUserId(userId: string): Promise<void> {
    await this.initialize();
    const userIdDatapointId = "mem0-user-id-record";
    const dimension = this.config.dimension || 768;
    const zeroVector = Array(dimension).fill(0.0);

