type ToastOptions = {
  title?: React.ReactNode;
  description?: React.ReactNode;
  variant?: ToastVariant;
};

function toast(options: ToastOptions) {
  const { title, description, variant = "default" } = options;
  const message =
    title != null
      ? String(title)
      : description != null
        ? String(description)
        : "Notification";
  const opts =
    title != null && description != null
      ? { description: String(description) }
      : {};

  if (variant === "destructive") {
    sonnerToast.error(message, opts);
  } else if (variant === "success") {
    sonnerToast.success(message, opts);
  } else {
    sonnerToast(message, opts);
  }

  return {
    id: "",
    dismiss: () => {},
    update: () => {},
  };
}

function useToast() {
  return React.useMemo(
    () => ({
      toasts: [],
      toast,
      dismiss: () => {},
    }),
    [],
  );
}

server/dashboard/src/hooks/use-api-query.source_code:
interface UseApiQueryOptions<T> {
  enabled?: boolean;
  errorToast?: string;
  initialData?: T;
}

interface UseApiQueryResult<T> {
  data: T | undefined;
  isLoading: boolean;
  error: string;
  refetch: () => Promise<void>;
}

function useApiQuery<T>(
  fetcher: () => Promise<T>,
  options: UseApiQueryOptions<T> = {},
): UseApiQueryResult<T> {
  const { enabled = true, errorToast, initialData } = options;

  const [data, setData] = useState<T | undefined>(initialData);
  const [isLoading, setIsLoading] = useState(enabled);
  const [error, setError] = useState("");

  const fetcherRef = useRef(fetcher);
  fetcherRef.current = fetcher;

  const run = useCallback(async () => {
    setIsLoading(true);
    setError("");
    try {
      setData(await fetcherRef.current());
    } catch (err) {
      const message = getErrorMessage(err, errorToast || "Request failed");
      setError(message);
      if (errorToast) {
        toast({
          title: errorToast,
          description: message,
          variant: "destructive",
        });
      }
    } finally {
      setIsLoading(false);
    }
  }, [errorToast]);

  useEffect(() => {
    if (enabled) void run();
  }, [enabled, run]);

  return { data, isLoading, error, refetch: run };
}

server/dashboard/src/hooks/useDebounce.t.source_code:
function useDebounce<T>(value: T, delay = 500): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(timer);
    };
  }, [value, delay]);

  return debouncedValue;
}

