	@kill -9 $$(lsof -ti:18789) 2>/dev/null || true
	@echo "Removing plugin..."
	@echo "y" | openclaw plugins uninstall openclaw-mem0 >/dev/null 2>&1 || true
	@echo "Cleaning build artifacts..."
