	@echo "Clean complete."

.github/workflows/issue-labeler.yml::lab.source_code:
label:
  runs-on: ubuntu-latest
  steps:
    - uses: actions/checkout@v4

    - uses: stefanbuck/github-issue-parser@v3
      id: issue-parser
      continue-on-error: true
      with:
        template-path: .github/ISSUE_TEMPLATE/bug_report.yml

    - uses: redhat-plumbers-in-action/advanced-issue-labeler@v3
      continue-on-error: true
      with:
        issue-form: ${{ steps.issue-parser.outputs.jsonString }}
        token: ${{ secrets.GITHUB_TOKEN }}
        config-path: .github/advanced-issue-labeler.yml

    - name: Infer component from text when the form was not used
      uses: actions/github-script@v7
      with:
        script: |
          const {
            componentLabels,
            inferComponentLabels,
            loadKeywords,
          } = require(`${process.env.GITHUB_WORKSPACE}/.github/scripts/infer-component-labels.js`);

          const { data: issue } = await github.rest.issues.get({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: context.issue.number,
          });

          const keywords = loadKeywords(`${process.env.GITHUB_WORKSPACE}/.github/component-keywords.json`);
          const known = componentLabels(keywords);
          const existing = issue.labels.map((label) => label.name || label);
          if (existing.some((name) => known.includes(name))) {
            core.info(`Component label already present: ${existing.join(', ')}`);
            return;
          }

          const labels = inferComponentLabels(`${issue.title}\n\n${issue.body || ''}`, keywords);

          if (labels.length === 0) {
            core.info('No component could be inferred from the issue text');
            return;
          }

          core.info(`Inferred: ${labels.join(', ')}`);
          await github.rest.issues.addLabels({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: context.issue.number,
            labels,
          });

.github/workflows/pr-gate.yml::gate.source_code:
gate:
  if: >-
    github.event_name == 'pull_request_target' &&
    github.event.action != 'edited' &&
    github.event.pull_request.draft == false &&
    github.event.pull_request.user.type != 'Bot' &&
    github.event.pull_request.head.repo.full_name != github.repository &&
    !contains(fromJSON('["OWNER","MEMBER","COLLABORATOR"]'), github.event.pull_request.author_association)
  runs-on: ubuntu-latest
  steps:
    - uses: actions/github-script@v7
      with:
        script: |
          const pr = context.payload.pull_request;
          const { owner, repo } = context.repo;

          const effectiveFrom = process.env.GATE_EFFECTIVE_FROM;
          if (effectiveFrom && Date.parse(pr.created_at) < Date.parse(effectiveFrom)) {
            core.info(`Opened ${pr.created_at}, before the gate took effect ${effectiveFrom}. Skipped.`);
            return;
          }

          const { data: current } = await github.rest.pulls.get({
            owner, repo, pull_number: pr.number,
          });
          if (current.state !== 'open') {
            core.info(`#${pr.number} is already ${current.state}. Skipped.`);
            return;
          }

          const files = await github.paginate(github.rest.pulls.listFiles, {
            owner, repo, pull_number: pr.number, per_page: 100,
          });
          const rootDocs = new Set(['README.md', 'CONTRIBUTING.md', 'CODE_OF_CONDUCT.md', 'SECURITY.md']);
          const isDocs = (filename) => filename.startsWith('docs/') || rootDocs.has(filename);
          if (files.length > 0 && files.every((file) => isDocs(file.filename))) {
            core.info('Docs-only PR, gate skipped');
            return;
          }

          const { repository } = await github.graphql(
            `query ($owner: String!, $repo: String!, $number: Int!) {
              repository(owner: $owner, name: $repo) {
                pullRequest(number: $number) {
                  closingIssuesReferences(first: 20) {
                    nodes { number labels(first: 50) { nodes { name } } }
                  }
                }
              }
            }`,
            { owner, repo, number: pr.number },
          );

          const accepted = repository.pullRequest.closingIssuesReferences.nodes
            .filter((issue) => issue.labels.nodes.some((label) => label.name === 'accepted'))
            .map((issue) => issue.number);

          if (accepted.length > 0) {
            core.info(`Accepted issue linked: #${accepted.join(', #')}`);
            return;
          }

          const body = [
            '<!-- pr-gate -->',
            'Thanks for taking the time to open this.',
            '',
            'We only review pull requests that fix an issue we have already agreed to take on, so this one is closed for now.',
            '**Closed does not mean rejected.** It means it is not in the queue yet, and reopening takes about a minute.',
            '',
            'To get it reviewed:',
            '',
            '1. Make sure an issue describes the problem, with the version you are on, a runnable reproduction, and the real output or traceback you saw.',
            '2. Link it from this pull request description with `Closes #<number>`.',
            '3. Ask a maintainer to label that issue `accepted`. This pull request reopens by itself when they do.',
            '',
            'Issue already labeled `accepted`? Just add `Closes #<number>` to the description. That reopens this too.',
            '',
            'Documentation-only changes skip this gate entirely.',
            '',
            'See [CONTRIBUTING.md](https://github.com/mem0ai/mem0/blob/main/CONTRIBUTING.md) for the full policy.',
          ].join('\n');

          await github.rest.issues.createComment({
            owner, repo, issue_number: pr.number, body,
          });
          await github.rest.pulls.update({
            owner, repo, pull_number: pr.number, state: 'closed',
          });
          core.info(`Closed #${pr.number}: no accepted issue linked`);

.github/workflows/pr-gate.yml::reopen.source_code:
reopen:
  if: >-
    (github.event_name == 'issues' && github.event.label.name == 'accepted') ||
    (github.event.action == 'edited' && github.event.pull_request.state == 'closed')
  runs-on: ubuntu-latest
  steps:
    - uses: actions/github-script@v7
      with:
        script: |
          const { owner, repo } = context.repo;
          const marker = '<!-- pr-gate -->';

          const denounced = await (async () => {
            try {
              const { data } = await github.rest.repos.getContent({
                owner, repo, path: '.github/VOUCHED.td',
                ref: context.payload.repository.default_branch,
              });
              return new Set(Buffer.from(data.content, 'base64').toString('utf8')
                .split('\n')
                .map((line) => line.trim())
                .filter((line) => line.startsWith('-'))
                .map((line) => line.slice(1).split(/\s+/)[0].split(':').pop().toLowerCase())
                .filter(Boolean));
            } catch (error) {
              core.warning(`Could not read VOUCHED.td, treating nobody as denounced: ${error.message}`);
              return new Set();
            }
          })();

          const isReopenable = async (number) => {
            const { repository } = await github.graphql(
              `query ($owner: String!, $repo: String!, $number: Int!) {
                repository(owner: $owner, name: $repo) {
                  pullRequest(number: $number) {
                    state
                    author { login }
                    closingIssuesReferences(first: 20) {
                      nodes { labels(first: 50) { nodes { name } } }
                    }
                  }
                }
              }`,
              { owner, repo, number },
            );
            const pullRequest = repository.pullRequest;
            if (denounced.has(pullRequest.author?.login?.toLowerCase())) {
              core.info(`#${number} is from a denounced author. Vouch outranks this gate.`);
              return false;
            }
            return pullRequest.state === 'CLOSED' &&
              pullRequest.closingIssuesReferences.nodes.some((issue) =>
                issue.labels.nodes.some((label) => label.name === 'accepted'));
          };

          let candidates;
          if (context.eventName === 'issues') {
            const { repository } = await github.graphql(
              `query ($owner: String!, $repo: String!, $number: Int!) {
                repository(owner: $owner, name: $repo) {
                  issue(number: $number) {
                    closedByPullRequestsReferences(first: 20, includeClosedPrs: true) {
                      nodes { number }
                    }
                  }
                }
              }`,
              { owner, repo, number: context.payload.issue.number },
            );
            candidates = repository.issue.closedByPullRequestsReferences.nodes.map((pr) => pr.number);
          } else {
            candidates = [context.payload.pull_request.number];
          }

          for (const number of candidates) {
            if (!(await isReopenable(number))) {
              core.info(`#${number} is not a closed pull request linking an accepted issue. Skipped.`);
              continue;
            }

            const comments = await github.paginate(github.rest.issues.listComments, {
              owner, repo, issue_number: number, per_page: 100,
            });
            if (!comments.some((comment) => comment.body?.startsWith(marker))) {
              core.info(`#${number} was not closed by this gate. Left alone.`);
              continue;
            }

            try {
              await github.rest.pulls.update({
                owner, repo, pull_number: number, state: 'open',
              });
            } catch (error) {
              core.warning(`Could not reopen #${number}: ${error.message}`);
              continue;
            }

            await github.rest.issues.createComment({
              owner, repo, issue_number: number,
              body: 'An `accepted` issue is linked now, so this is open again and ready for review.',
            });
            core.info(`Reopened #${number}`);
          }

.github/workflows/pr-labeler.yml::label.source_code:
label:
  runs-on: ubuntu-latest
  steps:
    - uses: actions/labeler@v5
      with:
        repo-token: ${{ secrets.GITHUB_TOKEN }}

    - name: Propagate labels from linked issues
      uses: actions/github-script@v7
      with:
        script: |
          const allowed = new Set([
            'sdk-python', 'sdk-typescript', 'vector-store', 'plugin',
            'rest-api', 'documentation', 'ci', 'cli', 'integrations',
          ]);
          const umbrella = { plugin: 'integrations' };
          const { repository } = await github.graphql(
            `query ($owner: String!, $repo: String!, $number: Int!) {
              repository(owner: $owner, name: $repo) {
                pullRequest(number: $number) {
                  closingIssuesReferences(first: 20) {
                    nodes { labels(first: 50) { nodes { name } } }
                  }
                }
              }
            }`,
            { owner: context.repo.owner, repo: context.repo.repo, number: context.issue.number },
          );

          const labels = new Set();
          for (const issue of repository.pullRequest.closingIssuesReferences.nodes) {
            for (const label of issue.labels.nodes) {
              if (allowed.has(label.name)) labels.add(label.name);
            }
          }

          for (const label of [...labels]) {
            if (umbrella[label]) labels.add(umbrella[label]);
          }

          if (labels.size > 0) {
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: [...labels],
            });
          }

.github/workflows/release.yml::route.source_code:
route:
  name: Route ${{ github.event.release.tag_name }} to its CD pipeline
  runs-on: ubuntu-latest
  steps:
    - name: Match tag prefix to CD workflow
      id: match
      env:
        TAG: ${{ github.event.release.tag_name }}
      run: |
        # Specific package prefixes first; the bare v* (Python SDK) arm
        # must stay last so prefixed tags that also start with 'v'
        # (vercel-ai-v*) can never be routed to the Python pipeline.
        case "$TAG" in
          ts-v*)        workflow="ts-sdk-cd.yml" ;;
          cli-node-v*)  workflow="cli-node-cd.yml" ;;
          cli-v*)       workflow="cli-python-cd.yml" ;;
          vercel-ai-v*) workflow="vercel-ai-cd.yml" ;;
          openclaw-v*)  workflow="openclaw-cd.yml" ;;
          opencode-v*)  workflow="opencode-plugin-cd.yml" ;;
          pi-agent-v*)  workflow="pi-agent-plugin-cd.yml" ;;
          deepseek-plugin-v*)  workflow="deepseek-plugin-cd.yml" ;;
          n8n-nodes-mem0-v*) workflow="n8n-nodes-mem0-cd.yml" ;;
          mem0-strands-v*)   workflow="mem0-strands-cd.yml" ;;
          v*)           workflow="cd.yml" ;;
          *)
            echo "::error::Release tag '$TAG' does not match any known package prefix — nothing will be published. See the tag prefix table in AGENTS.md."
            exit 1
            ;;
        esac
        echo "workflow=$workflow" >> "$GITHUB_OUTPUT"
        echo ":outbox_tray: Routed \`$TAG\` → \`$workflow\`" >> "$GITHUB_STEP_SUMMARY"

    - name: Dispatch ${{ steps.match.outputs.workflow }}
      env:
        GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        TAG: ${{ github.event.release.tag_name }}
      run: |
        # --ref points at the tag so the dispatched run builds (and signs
        # provenance for) the exact tagged commit.
        gh workflow run "${{ steps.match.outputs.workflow }}" \
          --repo "$GITHUB_REPOSITORY" \
          --ref "refs/tags/$TAG" \
          -f tag="$TAG" \
          -f prerelease="${{ github.event.release.prerelease }}"

.github/workflows/vouch-check-pr.yml::ch.source_code:
check:
  if: >-
    github.event.pull_request.user.type != 'Bot' &&
    github.event.pull_request.head.repo.full_name != github.repository &&
    !contains(fromJSON('["OWNER","MEMBER","COLLABORATOR"]'), github.event.pull_request.author_association)
  runs-on: ubuntu-latest
  steps:
    - uses: mitchellh/vouch/action/check-pr@d66fa29a64600490892131ad87597c30c91fcac4 # v1.5.0
      id: vouch
      with:
        pr-number: ${{ github.event.pull_request.number }}
        require-vouch: false
        auto-close: true
      env:
        GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

    - if: steps.vouch.outputs.status == 'allowed'
      uses: actions/github-script@v7
      with:
        script: |
          const { owner, repo } = context.repo;
          const pr = context.payload.pull_request;
          const marker = '<!-- vouch-check -->';

          const comments = await github.paginate(github.rest.issues.listComments, {
            owner, repo, issue_number: pr.number, per_page: 100,
          });
          if (comments.some((comment) => comment.body?.startsWith(marker))) {
            core.info('Vouch comment already posted, skipped.');
            return;
          }

          const body = [
            marker,
            `Hi @${context.payload.pull_request.user.login}, thanks for opening this pull request.`,
            '',
            "This is just a soft check: you are not yet in this repo's vouched contributor list (`.github/VOUCHED.td`). Nothing is blocked and there is nothing you need to do.",
            '',
            `A maintainer can vouch for you by commenting \`!vouch @${context.payload.pull_request.user.login}\` on any issue.`,
          ].join('\n');

          await github.rest.issues.createComment({
            owner, repo, issue_number: pr.number, body,
          });

.github/workflows/vouch-manage-by-issue..source_code:
manage:
  if: contains(github.event.comment.body, '!vouch') || contains(github.event.comment.body, '!denounce') || contains(github.event.comment.body, '!unvouch')
  runs-on: ubuntu-latest
  steps:
    - uses: actions/create-github-app-token@v3
      id: app-token
      with:
        app-id: ${{ secrets.VOUCH_APP_ID }}
        private-key: ${{ secrets.VOUCH_APP_PRIVATE_KEY }}

    - uses: actions/checkout@v4
      with:
        token: ${{ steps.app-token.outputs.token }}

    - uses: mitchellh/vouch/action/manage-by-issue@d66fa29a64600490892131ad87597c30c91fcac4 # v1.5.0
      with:
        repo: ${{ github.repository }}
        issue-id: ${{ github.event.issue.number }}
        comment-id: ${{ github.event.comment.id }}
        vouch-keyword: "!vouch"
        denounce-keyword: "!denounce"
        unvouch-keyword: "!unvouch"
        pull-request: "true"
        merge-immediately: "false"
      env:
        GITHUB_TOKEN: ${{ steps.app-token.outputs.token }}
